export const FINANCE_VOIDS: Void[] = [
  { what: "PIB (pib.gov.in) returned HTTP 403 to both curl and WebFetch here, so the Ministry of Finance signing releases (e.g., PRID 1987890 on the RRTS JPY 37bn tranche; PRID 2196326 on US$800m of ADB loans; relid 136294 on Pandian) could not be opened; signatories (Additional Secretary DEA; ADB Country Director) are therefore not recorded.", whyItMatters: "The brief asks who signed at approval; the primary Indian record of signatories is PIB. SPEC probe said PIB 200; not so from this session.", srcs: [["ADB PDS 51073-005 — Delhi-Meerut RRTS Tranche 3","https://www.adb.org/projects/51073-005/main"]], domain: "adb-aiib" },
  { what: "ADB Board of Governors directory pages (/who-we-are/about/board-governors, /about/governors, /new/who-we-are/alt-governors) all return 404; the Finance Minister's ex officio ADB Governorship could not be documented from ADB.", whyItMatters: "Sitharaman (FM 2019-05-31→) is not given a role claim here rather than assert an unopened source.", srcs: [["ADB — India and ADB (country page)","https://www.adb.org/where-we-work/india"]], domain: "adb-aiib" },
  { what: "No ADB or AIIB financing of Adani Green Energy found: adb.org searches return no Adani project; AIIB's data file has no Adani entry. The AIIB \"AGPCGPL\" city-gas project (2021, cancelled) is AG&P City Gas, a name collision, not Adani.", whyItMatters: "The brief flagged \"Adani Green? verify\" — the documented absence is the finding; MDB private windows have not been a source of Adani Green funding.", srcs: [["AIIB — all-projects data file behind the project list (server-served JS)","https://www.aiib.org/en/projects/list/.content/all-projects-data.js"]], domain: "adb-aiib" },
  { what: "No ADB nonsovereign record for a Mahindra group company surfaced in the search; not verified either way.", whyItMatters: "Listed in the brief; remains a gap, not a void.", srcs: [], domain: "adb-aiib" },
  { what: "Neither ADB PDS pages nor AIIB project pages publish loan pricing (benchmark, spread, tenor, grace). Terms fields are therefore null except instrument type and on-page conditions.", whyItMatters: "The political question is conditionality and price; the public project pages carry neither. Loan agreements (ADB \"LA\" documents) would.", srcs: [["ADB PDS 54182-001 — COVID-19 Active Response and Expenditure Support Program","https://www.adb.org/projects/54182-001/main"],["AIIB project 000409 — India: COVID-19 Active Response and Expenditure Support (CARES)","https://www.aiib.org/en/projects/details/2020/approved/India-COVID-19-Active-Response-and-Expenditure-Support.html"]], domain: "adb-aiib" },
  { what: "AIIB members/voting table is client-rendered; CRS brief IF10154 download returned 202 with 0 bytes; India's and China's voting shares rest on press (Diplomat, FPJ).", whyItMatters: "Shareholding is the spine of the \"China-controlled bank\" narrative; it is recorded as reported, not documented.", srcs: [["AIIB — Members of the Bank (table is client-rendered; figures not readable here)","https://www.aiib.org/en/about-aiib/governance/members-of-bank/index.html"]], domain: "adb-aiib" },
  { what: "No Adani Power Mundra loan from CDB/China Eximbank/BOC/ICBC appears among AidData GCDF 3.0's 113 India records (only Adani Power Maharashtra's 2013 Tiroda syndicate does). GMR and GVK do not appear as borrowers at all.", whyItMatters: "The brief expected Mundra (2010–11) and GMR/GVK rows; the dataset's absence means either the credits were commercial-bank (non-official) or unrecorded. Record the absence rather than a number.", srcs: [["AidData GCDF 3.0 dataset download (zip, 28.6 MB; sheet GCDF_3.0; 113 India rows extracted 2026-09-26)","https://docs.aiddata.org/ad4/datasets/AidDatas_Global_Chinese_Development_Finance_Dataset_Version_3_0.zip"]], domain: "bilateral-china" },
  { what: "KfW project-level records (metros, solar, Green Energy Corridor) could not be opened: kfw.de is blocked; powermin.gov.in GEC page 404; no PIB release located without search.", whyItMatters: "Germany is India's third-largest bilateral creditor (US$3.75bn, 2023) yet has zero loan claims in this file — a reachability void, not an absence of lending.", srcs: [["World Bank International Debt Statistics API — India, PPG bilateral debt outstanding (DT.DOD.BLAT.CD) by counterpart, 2010/2014/2023","https://api.worldbank.org/v2/sources/6/country/IND/series/DT.DOD.BLAT.CD/counterpart-area/all/time/YR2023;YR2014;YR2010?format=json&per_page=1000"]], domain: "bilateral-china" },
  { what: "No minister is named as signatory on any JICA, NDB or AFD loan document opened; JICA agreements are signed by DEA Joint/Additional Secretaries and the JICA Chief Representative; Exchange of Notes (Ambassador ↔ DEA Secretary) releases sit on mofa.go.jp / in.emb-japan.go.jp, both 403 from this environment.", whyItMatters: "The 'ministers at signing' join can only be made by date (FM in office), which this file does via budget-speech anchors; the political signature is the E/N, which was not obtainable.", srcs: [["JICA India office press release 2026-03-24 — ¥62,294m loan for Maharashtra tertiary healthcare (signatories named)","https://www.jica.go.jp/english/overseas/india/information/press/2025/1579722_59609.html"],["JICA press release 2018-10-01 — signing of MAHSR (I) ¥89.547bn and Kolkata East-West Metro (III) (PDF)","https://www2.jica.go.jp/yen_loan/pdf/en/6978/20181001_01.pdf"]], domain: "bilateral-china" },
  { what: "MEA's 2017-05-13 statement declining to attend the Belt and Road Forum could not be read: the page returns HTTP 200 but its body is client-rendered.", whyItMatters: "It is the primary record for India's non-participation in BRI — the control for the 'debt-trap' narrative — and is cited here from the URL only, not from verified text.", srcs: [["MEA — Official Spokesperson's response to a query on participation of India in OBOR/BRI Forum (2017-05-13) — page opened (HTTP 200) but body is client-rendered; text not verifiable from this environment","https://www.mea.gov.in/media-briefings.htm?dtl/28463/Official_Spokespersons_response_to_a_query_on_participation_of_India_in_OBORBRI_Forum"]], domain: "bilateral-china" },
  { what: "DPIIT's own Press Note 3 (2020) PDF and the RBI Master Direction PDF were unreachable (404 / blocked); the rule text is taken from PIB's release reproducing the amended paragraph.", whyItMatters: "PIB is an official record and sufficient for 'documented', but the gazetted FEMA (NDI) Amendment Rules 2020 (S.O. dated 2020-04-22) were not seen.", srcs: [["PIB 2020-04-18 (PRID 1615711) — Government amends the extant FDI policy for curbing opportunistic takeovers/acquisitions (Press Note 3 (2020 Series) text)","https://pib.gov.in/PressReleasePage.aspx?PRID=1615711"]], domain: "bilateral-china" },
  { what: "NHSRCL's funding/status page reset the connection; no current MAHSR cost, JICA-loan share or revised completion date from an Indian primary source.", whyItMatters: "The 'vanity loan' narrative turns on cost escalation and the ₹ counterpart, which this file can only bound from JICA's 2018 ex-ante figure.", srcs: [["JICA Ex-Ante Evaluation — Project for Construction of Mumbai–Ahmedabad High Speed Rail (I), L/A 2018-09-28 (PDF)","https://www2.jica.go.jp/en/evaluation/pdf/2018_ID-P277_1_f.pdf"]], domain: "bilateral-china" },
  { what: "Post-2016 World Bank (STEP) contract award notices list only the awarded firm; evaluated/losing bidders and their prices are not published. 315 of 370 sampled notices (85%) — including every EDFC-3, NMCG, NHIIP-2016 and PMGSY award — have no observable bid count.", whyItMatters: "Concentration without a bidder count cannot be read as either competition or capture; the largest single L&T award (₹2,871 cr CP-303) and all Ganga HAM awards sit in this blind spot.", srcs: [["World Bank procurement notices API — project P150158 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P150158&rows=200"],["World Bank procurement notices API — project P119085 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P119085&rows=200"],["World Bank project procurement page P131765 (server HTML; awards are loaded from the procnotices API)","https://projects.worldbank.org/en/projects-operations/project-procurement/P131765"]], domain: "contracts" },
  { what: "World Bank Data Catalog / Major Contract Awards dataset returned 429 (rate-limited) and finances.worldbank.org redirected without data; the search.worldbank.org 'contractdata' endpoint is 404.", whyItMatters: "The Bank's consolidated supplier-level contract dataset (supplier country, amount, method) could not be used; the per-project notices feed substituted for it.", srcs: [["World Bank project procurement page P131765 (server HTML; awards are loaded from the procnotices API)","https://projects.worldbank.org/en/projects-operations/project-procurement/P131765"]], domain: "contracts" },
  { what: "World Bank press releases explaining the Madhucon (2017) and A2Z (2020) debarments — which project, what conduct — were not reachable (guessed URLs 404; Bank news/documents APIs returned 0 results for both names).", whyItMatters: "The listing gives the clause, not the facts; without the release the ground cannot be tied to a specific Indian project.", srcs: [["World Bank Listing of Ineligible Firms & Individuals — sanctions data API (as served to worldbank.org/debarred-firms, read 2026-09-26)","https://apigwext.worldbank.org/dvsvc/v1.0/json/APPLICATION/ADOBE_EXPRNCE_MGR/FIRM/SANCTIONED_FIRM"]], domain: "contracts" },
  { what: "ADB publishes for RRTS only a procurement plan with estimated package values and LOA dates; contract prices, bidder lists and bid prices are not on adb.org (the Tenders search for 51073 returns no award records).", whyItMatters: "RRTS concentration figures are on estimated values; only Package 4 has a documented price and field, and that from press.", srcs: [["ADB — Delhi–Meerut RRTS Procurement Plan Rev 7.0 (PDF: methods, awarded packages, estimated values, LOA dates)","https://www.adb.org/sites/default/files/project-documents/51073/51073-003-51073-004-pp-en.pdf"],["ADB Projects & Tenders search for 51073 (no per-project contract-award records served)","https://www.adb.org/projects/tenders?terms=51073"]], domain: "contracts" },
  { what: "PMGSY Rural Roads (P124639) has 430 notices but the feed capped at 200 rows and every row returned was a Meghalaya SRRDA package (₹1,204 cr in 196 awards, all RFB, no bidder lists); other states' PMGSY awards under the loan are not in the returned sample.", whyItMatters: "The rural-roads component — 1.4bn US$, the third-largest project — is unobservable at supplier level from this pass.", srcs: [["World Bank procurement notices API — project P124639 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P124639&rows=200"]], domain: "contracts" },
  { what: "Four sampled projects (P147820 Solar/SECI, P050668 MUTP, P144447 Elementary Education, P067606 UP Roads) return zero procurement notices — either pre-notice-era or financial-intermediary/results operations with no Bank-published awards.", whyItMatters: "'Who got the contracts' is undefined for on-lending and results-based operations; the question shifts to the intermediary's own procurement (SECI's solar park tenders, state education departments).", srcs: [["World Bank procurement notices API — project P147820 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P147820&rows=200"],["World Bank procurement notices API — project P050668 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P050668&rows=200"],["World Bank procurement notices API — project P144447 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P144447&rows=200"],["World Bank procurement notices API — project P067606 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P067606&rows=200"]], domain: "contracts" },
  { what: "The GFR Order annexures (which would say whether multilateral-financed tenders under existing loan agreements are carved out) were not fetched; the PIB summary is silent on it.", whyItMatters: "Whether NCRTC needed a waiver or was exempt by the Order's own terms is the legal crux of the STEC episode.", srcs: [["PIB — Ministry of Finance, 'Restrictions on Public Procurement from certain countries', 2020-07-23 (Release ID 1640778)","https://pib.gov.in/PressReleasePage.aspx?PRID=1640778"]], domain: "contracts" },
  { what: "dea.gov.in and indiabudget.gov.in (the two official homes of DEA's quarterly \"India's External Debt: A Status Report\") were both unreachable this session (dea.gov.in: connection failure; indiabudget.gov.in: HTTP 403 via both WebFetch and curl through the proxy).", whyItMatters: "Every external-debt figure in this file is therefore sourced to the World Bank's DT.* series (a different, calendar-year, current-US$ framework) rather than to RBI/DEA's own fiscal-year, India-specific classification (which separately itemises NRI deposits, ECBs and trade credit) — the two are close but not identical, and RBI's own status report would let the composition be restated in the categories the Ministry of Finance itself uses.", srcs: [["World Bank — India country page (used as substitute)","https://www.worldbank.org/en/country/india"]], domain: "debt-imf-people" },
  { what: "imf.org and data.imf.org were blocked for this session (403 on the one HTML press-release URL tried; a PDF fetch of an IMF history chapter returned only unusable binary/font metadata).", whyItMatters: "India's current IMF quota share, the identity of any successor to K.V. Subramanian as Executive Director (the post was reported vacant as of 3 May 2025 and no successor was found in accessible sources as of this session), and the IMF's own primary account of the 1981 and 1991 programmes could not be directly verified — every IMF-related claim in this file is sourced through Indian press coverage of IMF statements, not IMF primary documents.", srcs: [], domain: "debt-imf-people" },
  { what: "No on-the-record response from Krishnamurthy Subramanian to the reported reasons for his early exit from the IMF Executive Board was found in any source opened this session.", whyItMatters: "The contradiction invariant requires that an allegation implying impropriety ship with the concerned party's response; recorded as \"No response recorded — asked/not asked unknown\" (claim debt:c021) rather than left unanswered.", srcs: [], domain: "debt-imf-people" },
  { what: "No IEG country-programme evaluation of the World Bank in India after the 2001 OED Country Assistance Evaluation (Report No. 22134) was returned by the Documents & Reports API; the 2002 items are sector working papers under that CAE.", whyItMatters: "The lender's own verdict on its India programme — conditionality, state selection, procurement — is a quarter-century old; later assessments exist only at project level (ICR Reviews in worldbank.json) or in CPF completion reviews not located here.", srcs: [["WB Documents API — India CAE query","https://search.worldbank.org/api/v2/wds?format=json&qterm=%22India%22%20%22Country%20Assistance%20Evaluation%22%20OED&rows=10&fl=docna,docdt,docty,url,pdfurl,txturl&strdate=2000-01-01&enddate=2005-12-31"],["WB Documents API — first India IEG query","https://search.worldbank.org/api/v2/wds?format=json&qterm=India%20Country%20Program%20Evaluation%20Independent%20Evaluation%20Group&rows=10&fl=docna,docdt,docty,url,pdfurl,txturl"]], domain: "literature" },
  { what: "The World Bank GIA verification report (2020-12-08) lists no India data irregularity: nine irregularities across Azerbaijan, Saudi Arabia, UAE and China. India (Mumbai) appears only in the DB16 Getting Electricity change list reviewed, and a DB17 construction-permits methodology concern was 'reconfirmed' as not an irregularity.", whyItMatters: "The 'Doing Business was gamed for India' narrative rests on coincidence of timing; the primary audit record names other countries and records India's items as reviewed and cleared.", srcs: [["GIA verification report 2020-12-08","http://documents1.worldbank.org/curated/en/569901608154479291/txt/Management-Review-of-Data-Irregularities-in-the-Doing-Business-Reports-from-2016-to-2020-Verification-Report.txt"]], domain: "literature" },
  { what: "The OED CAE 2001 attributes India's lender-funded procurement problems to 'weaknesses in preparing bid documents and in contracting procedures, and delays in contract awards' — it records no finding of bidder collusion or a closed contractor pool.", whyItMatters: "The lender's own diagnosis of procurement failure in India is administrative delay, which is the boring explanation the 'closed club' narrative must displace.", srcs: [["OED India CAE 2001","http://documents1.worldbank.org/curated/en/813991468750240136/text/India-Country-assistance-evaluation.txt"]], domain: "literature" },
  { what: "The Supreme Court's 2024-04-01 order records that Article 293 'has not been so far the subject of an authoritative pronouncement of this Court'.", whyItMatters: "The legal basis of the Union's control over all state borrowing — including externally aided projects — was untested for 74 years; the Constitution Bench outcome (not located as of this sweep) will settle whether the 'DEA bottleneck' is a constitutional design or an overreach.", srcs: [["Indian Kanoon — Kerala v Union 2024-04-01","https://indiankanoon.org/doc/191833676/"]], domain: "literature" },
  { what: "No CAG audit report on externally aided projects could be located: cag.gov.in's audit-report search returned HTTP 404 and web search was capped.", whyItMatters: "The CAG's findings on commitment charges and undisbursed external loans are the domestic audit counterpart to IEG; without them the 'boring explanation' (money left undrawn costing commitment fees) cannot be quantified here.", srcs: [["OED India CAE 2001 (only audit-type record opened)","http://documents1.worldbank.org/curated/en/813991468750240136/text/India-Country-assistance-evaluation.txt"]], domain: "literature" },
  { what: "Loan conditions (prior actions, disbursement-linked indicators, procurement and safeguard covenants) are not in the Projects API; every claim carries terms.conditions = []", whyItMatters: "The political question about external finance is the conditionality, not the money; the Program Documents and Loan Agreements on each project page hold it", srcs: [["World Bank Projects API v3 (India)","https://search.worldbank.org/api/v3/projects?format=json&countrycode_exact=IN&rows=500&os=0&fl=id,project_name,boardapprovaldate,closingdate,status,borrower,impagency,totalcommamt,totalamt,grantamt,ibrdcommamt,curr_ibrd_commitment,idacommamt,curr_ida_commitment,curr_total_commitment,lendprojectcost,lendinginstr,projectfinancialtype,sector1,mjsector1,major_sector_name,theme1,regionname,url,project_abstract,pdo"]], domain: "worldbank-projects" },
  { what: "Interest rate, tenor and grace period are not in the API (ratePct, tenorYears, graceYears are null on every claim)", whyItMatters: "IBRD variable-spread loans and IDA credits differ by an order of magnitude in cost; the Loan/Financing Agreement states them", srcs: [["World Bank Projects API v3 (India)","https://search.worldbank.org/api/v3/projects?format=json&countrycode_exact=IN&rows=500&os=0&fl=id,project_name,boardapprovaldate,closingdate,status,borrower,impagency,totalcommamt,totalamt,grantamt,ibrdcommamt,curr_ibrd_commitment,idacommamt,curr_ida_commitment,curr_total_commitment,lendprojectcost,lendinginstr,projectfinancialtype,sector1,mjsector1,major_sector_name,theme1,regionname,url,project_abstract,pdo"]], domain: "worldbank-projects" },
  { what: "Borrower is blank for 504 of 849 loan claims; the Union (DEA) is recorded by default and each such claim says so in d", whyItMatters: "Sub-sovereign borrowers (SBI, IREDA, EESL, DFCCIL, state governments) exist in the record; a default can hide one", srcs: [["World Bank Projects API v3 (India)","https://search.worldbank.org/api/v3/projects?format=json&countrycode_exact=IN&rows=500&os=0&fl=id,project_name,boardapprovaldate,closingdate,status,borrower,impagency,totalcommamt,totalamt,grantamt,ibrdcommamt,curr_ibrd_commitment,idacommamt,curr_ida_commitment,curr_total_commitment,lendprojectcost,lendinginstr,projectfinancialtype,sector1,mjsector1,major_sector_name,theme1,regionname,url,project_abstract,pdo"]], domain: "worldbank-projects" },
  { what: "The lending instrument is missing for 97 non-dropped projects: the v3 index has no lendinginstr field and the v2 index covers 882 of 1,117 projects", whyItMatters: "Development Policy Lending (budget support with policy conditions) and Program-for-Results are the instruments that carry conditionality; an unknown instrument is an unknown condition set", srcs: [["World Bank Projects API v3 (India)","https://search.worldbank.org/api/v3/projects?format=json&countrycode_exact=IN&rows=500&os=0&fl=id,project_name,boardapprovaldate,closingdate,status,borrower,impagency,totalcommamt,totalamt,grantamt,ibrdcommamt,curr_ibrd_commitment,idacommamt,curr_ida_commitment,curr_total_commitment,lendprojectcost,lendinginstr,projectfinancialtype,sector1,mjsector1,major_sector_name,theme1,regionname,url,project_abstract,pdo"]], domain: "worldbank-projects" },
  { what: "Contracts awarded under these loans are not in the Projects API; the Data Catalog \"Major Contract Awards\" endpoint rate-limited (429) on 2026-09-26", whyItMatters: "Who wins the loan-funded contracts is the cui-bono question; the contracts domain must fetch the catalog or scrape the per-project procurement pages", srcs: [["World Bank Projects API v3 (India)","https://search.worldbank.org/api/v3/projects?format=json&countrycode_exact=IN&rows=500&os=0&fl=id,project_name,boardapprovaldate,closingdate,status,borrower,impagency,totalcommamt,totalamt,grantamt,ibrdcommamt,curr_ibrd_commitment,idacommamt,curr_ida_commitment,curr_total_commitment,lendprojectcost,lendinginstr,projectfinancialtype,sector1,mjsector1,major_sector_name,theme1,regionname,url,project_abstract,pdo"]], domain: "worldbank-projects" },
  { what: "Ministers, secretaries and chief ministers at approval, and the Executive Director for India at the Bank, are not in the API; this file has no persons and no role claims", whyItMatters: "Approval is a political act with named signatories; the people domain adds them by office-with-dates", srcs: [["World Bank Projects API v3 (India)","https://search.worldbank.org/api/v3/projects?format=json&countrycode_exact=IN&rows=500&os=0&fl=id,project_name,boardapprovaldate,closingdate,status,borrower,impagency,totalcommamt,totalamt,grantamt,ibrdcommamt,curr_ibrd_commitment,idacommamt,curr_ida_commitment,curr_total_commitment,lendprojectcost,lendinginstr,projectfinancialtype,sector1,mjsector1,major_sector_name,theme1,regionname,url,project_abstract,pdo"]], domain: "worldbank-projects" },
  { what: "Outcome ratings (ICR, IEG) are not in the API", whyItMatters: "The lender's own evaluation is the check on every claimed benefit", srcs: [["World Bank Projects API v3 (India)","https://search.worldbank.org/api/v3/projects?format=json&countrycode_exact=IN&rows=500&os=0&fl=id,project_name,boardapprovaldate,closingdate,status,borrower,impagency,totalcommamt,totalamt,grantamt,ibrdcommamt,curr_ibrd_commitment,idacommamt,curr_ida_commitment,curr_total_commitment,lendprojectcost,lendinginstr,projectfinancialtype,sector1,mjsector1,major_sector_name,theme1,regionname,url,project_abstract,pdo"]], domain: "worldbank-projects" },
  { what: "No World Bank document opened names the Union Finance Minister, a Chief Minister or a state finance minister. Agreements are signed by DEA Additional Secretaries and the Bank's Country Director; the political principals appear only through the offices ('led by the Chief Minister') in PDs.", whyItMatters: "The 'who signed' question has a bureaucratic answer in the primary record; attributing loans to ministers requires a second source (PIB signing releases name only officials).", srcs: [["PIB 2020-07-06 — GoI and World Bank sign US$750m MSME agreement","https://www.pib.gov.in/PressReleasePage.aspx?PRID=1636790"],["PIB 2020-12-16 — GoI and World Bank sign US$400m second COVID social protection operation","https://www.pib.gov.in/Pressreleaseshare.aspx?PRID=1681253"],["Program Document P169907 First Resilient Kerala DPO (2019-05-31)","https://documents.worldbank.org/curated/en/476681561946430308/text/India-First-Resilient-Kerala-Program-Development-Policy-Operation.txt"],["PAD P173704 Gujarat GOAL PforR (2021-02-27)","https://documents.worldbank.org/curated/en/945711616680968888/text/India-Gujarat-Outcomes-for-Accelerated-Learning-GOAL-Program-for-Results-Project.txt"]], domain: "worldbank" },
  { what: "The v3 projects API carries no lending-instrument or location field; the Data Catalog 'Major Contract Awards' set was rate-limited (429, per fleet SPEC). The loan→contractor join was therefore not made in this file.", whyItMatters: "Who gets the contracts the loans pay for is the central cui-bono question and remains open for the IPF/PforR projects.", srcs: [["World Bank Projects API v3 — India, rows 0–999","https://search.worldbank.org/api/v3/projects?format=json&countrycode_exact=IN&rows=1000&os=0&fl=id,project_name,boardapprovaldate,closingdate,curr_total_commitment,curr_ibrd_commitment,curr_ida_commitment,borrower,impagency,status,pdo"]], domain: "worldbank" },
  { what: "The Board of Executive Directors page is JavaScript-rendered; India's ED history (Khullar start date, S. Aparna and earlier) could not be read from the Bank's own site.", whyItMatters: "India's ED votes on every approval; the office-holder timeline is documented only via press.", srcs: [["World Bank — Boards of Directors page (JS-rendered; ED list not extractable)","https://www.worldbank.org/en/about/leadership/directors"],["Deccan Herald (PTI) — Iyer named World Bank ED replacing Rajesh Khullar","https://www.deccanherald.com/amp/india/b-v-r-subrahmanyam-appointed-niti-aayog-ceo-parameswaran-lyer-named-world-bank-ed-1193198.html"]], domain: "worldbank" },
  { what: "In the five Program Documents read, every prior action was already completed when the operation was appraised; two MSME prior actions predate the pandemic (2019-08-13 sandbox circular; 2018-11 PSB59).", whyItMatters: "A documented absence of new conditionality: the popular claim of Bank-dictated policy has no anchor in these operations; the forward triggers are where influence, if any, sits.", srcs: [["Program Document P173943 (2020-04-30)","https://documents.worldbank.org/curated/en/685311589767271707/text/India-Accelerating-Indias-COVID-19-Social-Protection-Response-Program.txt"],["Program Document P174292 MSME DPL (2020-06-16)","https://documents.worldbank.org/curated/en/703561593828083607/text/India-Micro-Small-and-Medium-Enterprises-Emergency-Response-Development-Policy-Loan.txt"],["Program Document P181032 First Low-Carbon Energy DPL (2023-06-02)","https://documents.worldbank.org/curated/en/099060623092565311/text/BOSIB0342f50d505508c7803e3b35fb5c59.txt"]], domain: "worldbank" },
];

export const FINANCE_NARRATIVES: Narrative[] = [
  { claim: "The Modi government borrowed ₹9,200 crore from a \"China-controlled\" bank (AIIB) in May–June 2020 while Indian soldiers were killed at Galwan.", status: "contested", strongestCase: "The borrowing is documented: AIIB US$500m health loan (signed 2020-05-08 per FPJ) and US$750m CARES (approved 2020-06-16, signed 2020-06-19, three days after the 15 June clash). China holds ~26.5% of AIIB votes and hosts the bank in Beijing; its president Jin Liqun said publicly he faced \"pressure at home\" to cut India lending.", strongestCounter: "Both loans were co-financed with ADB (US$1.5bn CARES) and the World Bank under the lead cofinancier's policies; India is AIIB's second-largest shareholder (~7.6%) and had a Vice-President (Pandian) heading its investment pipeline; the money is multilateral capital, not Chinese state finance, and the same programme was signed with ADB on 2020-04-28. A government official told Mint (quoted by the Diplomat): \"We are not taking money from China but from the multilateral development bank.\"", whatWouldChangeThis: "Evidence that AIIB imposed conditions distinct from ADB's, or that Chinese officials influenced the India loans; or, in the other direction, DEA records showing the loans were requested by India before the CRF window and merely fell on those dates.", srcs: [["Free Press Journal 2020-09-16 — Did the Modi government borrow from China-backed AIIB amid standoff?","https://www.freepressjournal.in/business/did-the-modi-government-borrow-from-china-backed-aiib-amid-standoff"],["AIIB project 000409 — India: COVID-19 Active Response and Expenditure Support (CARES)","https://www.aiib.org/en/projects/details/2020/approved/India-COVID-19-Active-Response-and-Expenditure-Support.html"],["ADB PDS 54182-001 — COVID-19 Active Response and Expenditure Support Program","https://www.adb.org/projects/54182-001/main"],["SCMP 2021-06-04 — AIIB maintained loans to India during border dispute, says president Jin Liqun","https://www.scmp.com/economy/global-economy/article/3136109/china-backed-aiib-maintained-loans-india-during-border"],["The Diplomat 2021-06-14 — Amid tensions with China, India proceeding with AIIB-funded projects","https://thediplomat.com/2021/06/amid-tensions-with-china-india-proceeding-with-aiib-funded-projects/"]], domain: "adb-aiib" },
  { claim: "AIIB quietly slowed or froze lending to India after the 2020 border clash.", status: "unsupported", strongestCase: "Four nonsovereign India deals approved 2019–22 were later cancelled; Chennai Peripheral Ring Road waited 34 months from concept to approval across the tension window; approvals fell in 2023–24.", strongestCounter: "AIIB's own data file shows India approvals of US$1.95bn (2020), US$1.95bn (2021) and US$1.87bn (2022) — each more than double 2019 — and 2025 approvals of US$1.64bn plus a US$1bn policy loan in July 2026. Jin Liqun and the Diplomat's project-by-project check (June 2021) found no halted India projects.", whatWouldChangeThis: "Pipeline documents showing India proposals withdrawn or deferred in 2020–22 for non-technical reasons.", srcs: [["AIIB — all-projects data file behind the project list (server-served JS)","https://www.aiib.org/en/projects/list/.content/all-projects-data.js"],["The Diplomat 2021-06-14 — Amid tensions with China, India proceeding with AIIB-funded projects","https://thediplomat.com/2021/06/amid-tensions-with-china-india-proceeding-with-aiib-funded-projects/"],["SCMP 2021-06-04 — AIIB maintained loans to India during border dispute, says president Jin Liqun","https://www.scmp.com/economy/global-economy/article/3136109/china-backed-aiib-maintained-loans-india-during-border"],["AIIB project 000336 — India: Chennai Peripheral Ring Road (Sections 2 and 3)","https://www.aiib.org/en/projects/details/2023/approved/India-Chennai-Peripheral-Ring-Road.html"]], domain: "adb-aiib" },
  { claim: "Multilateral lending to Indian states follows the party in power at the Centre — BJP-run states get the loans.", status: "unsupported", strongestCase: "Gujarat received AIIB's first India sovereign loan (2017) and a 2021 education programme; Assam has four AIIB loans; Maharashtra took the largest AIIB approval (US$1.1bn, 2025) under a BJP-led government.", strongestCounter: "ADB's own review names MP, Rajasthan and Bihar as the top recipients 2016–21 — Rajasthan under Congress for five of those years — and attributes the pattern to a 2013 rule sending 40–50% of lending to lower-income states. AIIB's state list includes Kerala (LDF), West Bengal (TMC), Tamil Nadu (DMK), Punjab (INC then AAP) and Andhra Pradesh (TDP then YSRCP). No per-capita normalisation was done here.", whatWouldChangeThis: "A per-capita, income-band-controlled comparison of state lending 2004–14 vs 2014–26 showing a residual party effect.", srcs: [["ADB — India CPS Final Review 2016–2021 (PDF, April 2022)","https://www.adb.org/sites/default/files/evaluation-document/832171/files/india-cpsfr.pdf"],["AIIB — all-projects data file behind the project list (server-served JS)","https://www.aiib.org/en/projects/list/.content/all-projects-data.js"]], domain: "adb-aiib" },
  { claim: "ADB/AIIB \"private-sector\" money is a subsidy channel to favoured renewable tycoons.", status: "speculative", strongestCase: "ReNew appears five times across ADB and AIIB (2014–2025) and inherited a sixth exposure via Ostro; ADB's own review says its equity was \"instrumental\" to Avaada's later fundraising; DFI debt is long-tenor and in effect cheaper than domestic bank debt for the same risk.", strongestCounter: "Every recorded deal is at market-based OCR pricing (not concessional), the offtake sits on competitively-auctioned SECI/state PPAs (₹4.69/kWh for ReNew Vyoman), ADB exited the 2014 ReNew equity in 2016 with \"satisfactory returns\", and the most politically discussed developer, Adani Green, has no ADB or AIIB record at all. Repeat lending to a proven sponsor is standard DFI behaviour.", whatWouldChangeThis: "Loan agreements showing below-market pricing or waived conditions for one sponsor relative to peers; or an ADB integrity finding.", srcs: [["ADB PDS 47926-014 — ReNew Power Investment Project (equity)","https://www.adb.org/projects/47926-014/main"],["ADB PDS 50195-001 — ReNew Clean Energy Project","https://www.adb.org/projects/50195-001/main"],["ADB PDS 51210-001 — Kutch Wind Project (Ostro Kutch Wind Pvt Ltd)","https://www.adb.org/projects/51210-001/main"],["ADB news 2025-11-10 — ADB, ReNew sign $331 million deal (Andhra Pradesh RTC plant)","https://www.adb.org/news/adb-renew-sign-331-million-deal-solar-wind-bess-power-plant-generating-24-7-clean-energy-india"],["AIIB project 000967 — India: ReNew Peak Power Project","https://www.aiib.org/en/projects/details/2025/approved/india-renew-peak-power-project.html"],["ADB PDS 52126-001 — Avaada Solar Project","https://www.adb.org/projects/52126-001/main"],["ADB — India CPS Final Review 2016–2021 (PDF, April 2022)","https://www.adb.org/sites/default/files/evaluation-document/832171/files/india-cpsfr.pdf"]], domain: "adb-aiib" },
  { claim: "Japan lends India far more, more cheaply and with fewer conditions than the multilateral banks.", status: "contested", strongestCase: "Cumulative Japanese ODA to India exceeds JPY 6.978 trillion; a single MAHSR tranche (₹22,627 crore, 2023) is larger than AIIB's annual India approvals; Japanese ODA loans are concessional by design.", strongestCounter: "Japan's loans are project-tied (MAHSR uses Shinkansen technology and Japanese contractors) whereas ADB/AIIB procurement is open to all member-country bidders; interest rates and tying conditions of the India loans were not verified in this session; ADB's cumulative US$63.8bn since 1986 is comparable in scale.", whatWouldChangeThis: "The JICA loan agreements' rate, tenor and procurement-eligibility clauses for the India portfolio.", srcs: [["Embassy of India, Tokyo — India-Japan economic relations","https://www.indembassy-tokyo.gov.in/eoityo_pages/NjQw"],["JICA press 2023-12-21 — ODA loan of JPY 400 billion (₹22,627 crore) for MAHSR tranche V","https://www.jica.go.jp/english/overseas/india/information/press/2023/20231221.html"],["JICA press 2025-03-27 — six ODA loan agreements, JPY 191,736 million (₹11,181 crore)","https://www.jica.go.jp/english/overseas/india/information/press/2024/1565705_53431.html"],["ADB — India and ADB (country page)","https://www.adb.org/where-we-work/india"]], domain: "adb-aiib" },
  { claim: "China has India in a 'debt trap' through Belt-and-Road-style lending.", status: "debunked", strongestCase: "Chinese state banks did lend heavily to Indian private groups in 2008–2015 (RCom ≈US$3.6bn, Sasan ≈US$1bn, Aircel, Lanco, APML, Essar), took security over licences and plant, and pursued promoters through NCLT and the London Commercial Court; Xi's 2014 visit produced US$2.8bn of bank credit-line pledges and US$1bn+ industrial-park pledges.", strongestCounter: "India is not a BRI participant and has no recorded sovereign bilateral debt to China in World Bank IDS (2010, 2014, 2023); 72% of its bilateral sovereign debt is owed to Japan at 0.1–2.7%. Every Chinese credit in AidData is to a private or SOE borrower at LIBOR-plus commercial spreads, and the largest borrowers defaulted on the Chinese banks, not the reverse — the lenders, not the borrower's sovereign, carried the loss. Debt-trap mechanics (sovereign collateral, asset seizure) are absent.", whatWouldChangeThis: "Discovery of sovereign or sovereign-guaranteed Chinese lending to the Union or a state; or Chinese-bank enforcement seizing strategic Indian infrastructure (none found).", srcs: [["World Bank International Debt Statistics API — India, PPG bilateral debt outstanding (DT.DOD.BLAT.CD) by counterpart, 2010/2014/2023","https://api.worldbank.org/v2/sources/6/country/IND/series/DT.DOD.BLAT.CD/counterpart-area/all/time/YR2023;YR2014;YR2010?format=json&per_page=1000"],["AidData GCDF 3.0 dataset download (zip, 28.6 MB; sheet GCDF_3.0; 113 India rows extracted 2026-09-26)","https://docs.aiddata.org/ad4/datasets/AidDatas_Global_Chinese_Development_Finance_Dataset_Version_3_0.zip"],["Economic Times 2018-01-06 — China Development Bank withdraws insolvency petition against Reliance Communications","https://economictimes.indiatimes.com/news/company/corporate-trends/china-development-bank-withdraws-insolvency-petition-against-reliance-communications/articleshow/62379700.cms"],["The Wire 2020-05-22 — UK court orders Anil Ambani to pay $717 million to Chinese banks within 21 days","https://thewire.in/business/uk-court-orders-anil-ambani-to-pay-717-million-to-chinese-banks-within-21-days"]], domain: "bilateral-china" },
  { claim: "Japanese ODA loans to India are 'strings-free'.", status: "contested", strongestCase: "Rates of 0.1–2.7% over 30–50 years with 10–15-year grace are far below market; most India loans in the same signing packages are 'General untied'; JICA imposes no policy conditionality of the DPL type; procurement runs through ICB and the executing agency.", strongestCounter: "The largest programme — MAHSR, ¥1.05 trillion — is explicitly 'Tied': JICA's ex-ante evaluation records that both governments 'agreed that the tied loan will be made … in order to utilize the technology and knowledge of Japan', reserving core Shinkansen packages for Japanese suppliers; the training-institute loan is tied too. The string is commercial (supplier exclusivity), not political, and it is disclosed.", whatWouldChangeThis: "Contract-level data on the Japanese share of MAHSR awards (JICA procurement notices) would size the string; a shift of later tranches to untied terms would weaken it.", srcs: [["JICA Ex-Ante Evaluation — Project for Construction of Mumbai–Ahmedabad High Speed Rail (I), L/A 2018-09-28 (PDF)","https://www2.jica.go.jp/en/evaluation/pdf/2018_ID-P277_1_f.pdf"],["JICA press release 2018-10-01 — signing of MAHSR (I) ¥89.547bn and Kolkata East-West Metro (III) (PDF)","https://www2.jica.go.jp/yen_loan/pdf/en/6978/20181001_01.pdf"],["JICA press release 2017-09-15 — signing of four ODA loans incl. MAHSR Training Institute and DFC electric locomotives (PDF)","https://www2.jica.go.jp/yen_loan/pdf/en/6906/20170915_01.pdf"],["JICA ODA Loan Project DATA — India (search result, all sectors)","https://www2.jica.go.jp/en/yen_loan/index.php/module/search?anken_name=&area1=0&area2=0&area3=0&country1=11&country2=0&country3=0&section1=0&section2=0&section3=0&industry1=0&industry2=0&industry3=0&anken_kubun=0&chotatsu_kubun=0&from_year=&to_year=&currency=jpy&submit=Search"]], domain: "bilateral-china" },
  { claim: "The bullet train is a 'vanity loan' — an expensive prestige project India did not need.", status: "contested", strongestCase: "¥1,050,000m committed against a 2018 ex-ante cost of ¥1,806,282m, a Dec-2023 planned completion missed while tranche V was still being signed in Dec 2023; tied procurement removes price competition; the yen counterpart and cost escalation could not be verified from Indian sources (NHSRCL unreachable).", strongestCounter: "At 0.1% over 50 years with 15 years' grace, the loan is close to a grant in present-value terms; India bears yen exchange risk but negligible interest; delays trace to Maharashtra land acquisition rather than lender behaviour; JICA's ex-ante document sets out traffic, time-saving and pollution indicators against which the project can be evaluated ex post.", whatWouldChangeThis: "A JICA ex-post evaluation or CAG audit giving realised cost, ridership and the yen-depreciation effect; a Parliament answer on the current ₹ cost and JICA share.", srcs: [["JICA ODA Loan Project DATA — India, 'High Speed' (MAHSR tranches I–V and training institute)","https://www2.jica.go.jp/en/yen_loan/index.php/module/search?anken_name=High+Speed&area1=0&area2=0&area3=0&country1=11&country2=0&country3=0&section1=0&section2=0&section3=0&industry1=0&industry2=0&industry3=0&anken_kubun=0&chotatsu_kubun=0&from_year=&to_year=&currency=jpy&submit=Search"],["JICA Ex-Ante Evaluation — Project for Construction of Mumbai–Ahmedabad High Speed Rail (I), L/A 2018-09-28 (PDF)","https://www2.jica.go.jp/en/evaluation/pdf/2018_ID-P277_1_f.pdf"],["JICA press release 2018-10-01 — signing of MAHSR (I) ¥89.547bn and Kolkata East-West Metro (III) (PDF)","https://www2.jica.go.jp/yen_loan/pdf/en/6978/20181001_01.pdf"],["JICA press release 2023-12-22 — two loans ¥415,301m incl. MAHSR (V) ¥400,000m","https://www.jica.go.jp/english/information/press/2023/20231222_30.html"]], domain: "bilateral-china" },
  { claim: "The Modi government handed a Chinese state firm a ₹1,126 crore Delhi–Meerut tunnel contract while Indian soldiers were dying at Galwan.", status: "contested", strongestCase: "The facts of the award are established: STEC, a Chinese SOE, was L1 on 2020-06-12 (three days before the Galwan clash), the government's own July 2020 Order was meant to keep such bidders out of public procurement, and NCRTC nonetheless issued the LOA on 2020-12-09 while the LAC standoff continued (National Herald framing).", strongestCounter: "The tender was governed by ADB's member-country eligibility rule under a loan the Union had already signed; five firms bid and all qualified; STEC's price was ₹44 cr below L&T's; the Order's own text says pending tenders past first-stage qualification would 'ordinarily' be cancelled — cancelling and re-tendering would have cost at least ₹44 cr and a year, and Chinese firms had won seven World Bank-financed Indian packages in 2011–2016 without objection. NCRTC: 'awarded following the set procedure and guidelines'.", whatWouldChangeThis: "A DoE/ADB record showing India sought and was refused STEC's exclusion, or a waiver granted specifically for this package, would move it to 'well-supported' as a lender-constraint story; evidence that NCRTC had discretion to reject the L1 and chose not to would move it toward the critics.", srcs: [["National Herald — 'Chinese firm given contract worth Rs 1,126 crore for Delhi-Meerut rail tunnel even as LAC standoff continues' (PTI-based, Jan 2021)","https://www.nationalheraldindia.com/india/chinese-firm-given-contract-worth-rs-1126-crore-for-delhi-meerut-rail-tunnel-even-as-lac-standoff-continues"],["The Tribune — 'Chinese firm bags rapid rail contract' (Sandeep Dikshit, 2021-01-03/04)","https://www.tribuneindia.com/news/nation/chinese-firm-bags-rapid-rail-contract-193265"],["Urban Transport News — 'STEC wins Rs 1,126 crore civil contract package 4 of Delhi-Meerut RRTS project' (2020-06-12; all five financial bids)","https://www.urbantransportnews.com/news/stec-bags-rs-1126-crore-civil-contract-package-4-of-delhi-meerut-rrts-line"],["ADB — Delhi–Meerut RRTS Procurement Plan Rev 7.0 (PDF: methods, awarded packages, estimated values, LOA dates)","https://www.adb.org/sites/default/files/project-documents/51073/51073-003-51073-004-pp-en.pdf"],["PIB — Ministry of Finance, 'Restrictions on Public Procurement from certain countries', 2020-07-23 (Release ID 1640778)","https://pib.gov.in/PressReleasePage.aspx?PRID=1640778"]], domain: "contracts" },
  { claim: "Lender-funded procurement in India is more open and competitive than domestic government procurement.", status: "well-supported", strongestCase: "55 World Bank ICB awards with published fields (2011–2016) average 5.6 bidders with no single-bid award, 20 of 55 won by foreign-led bidders including Chinese, Korean, UK, Mexican and Saudi firms; the ADB RRTS Package 4 drew five qualified bidders from three countries. The domestic control register records bidder counts for only 16 of 88 awards (mean 4.25) and no losing bidders for the rest.", strongestCounter: "Since 2016 the Bank's own notices stopped publishing losing bidders, so 85% of recent lender-funded awards are as opaque as domestic ones; and the domestic register's lower count may reflect disclosure, not competition. Concentration outcomes are similar: L&T 20% of WB value vs PSU-GoI 30.5% / Reliance 26% (spectrum-driven) of the domestic register.", whatWouldChangeThis: "CPPP bid-opening data for ₹500 cr+ Union works with mean bidders ≥5.5 would erase the difference; DFCCIL bid records for EDFC-3 showing 4+ responsive bidders would strengthen it.", srcs: [["World Bank procurement notices API — project P115566 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P115566&rows=200"],["World Bank procurement notices API — project P131765 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P131765&rows=20"],["World Bank procurement notices API — project P114338 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P114338&rows=200"],["Urban Transport News — 'STEC wins Rs 1,126 crore civil contract package 4 of Delhi-Meerut RRTS project' (2020-06-12; all five financial bids)","https://www.urbantransportnews.com/news/stec-bags-rs-1126-crore-civil-contract-package-4-of-delhi-meerut-rrts-line"],["ICIP domestic control register — research/raw/tenders-centre.json (88 Union-government awards, 2019–2026)","research/raw/tenders-centre.json"]], domain: "contracts" },
  { claim: "L&T wins everything the World Bank and ADB fund in India.", status: "contested", strongestCase: "L&T is the top winner in both feeds: 20.3% of World Bank-notice value (₹6,076 cr, incl. all three EDFC-3 packages) and 35.1% of ADB RRTS estimated value (three packages).", strongestCounter: "In the only period with published fields L&T lost five of six World Bank ICB bids it entered (to GIL-TPL JV twice, KEC and Bajaj twice), lost RRTS Package 4 to STEC, and does not appear at all in the 88-award domestic register; the largest single WB award (₹3,275 cr HVDC) went to Alstom UK and the largest civil pair (₹5,081 cr) to GIL-SIL JV.", whatWouldChangeThis: "DFCCIL/NCRTC bid-opening records showing L&T as sole responsive bidder on CP-303/304/305 or P3/P7/P17 would support the claim; records showing 3+ bidders would kill it.", srcs: [["World Bank procurement notices API — project P150158 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P150158&rows=200"],["World Bank procurement notices API — project P114338 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P114338&rows=200"],["World Bank procurement notices API — project P115566 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P115566&rows=200"],["ADB — Delhi–Meerut RRTS Procurement Plan Rev 7.0 (PDF: methods, awarded packages, estimated values, LOA dates)","https://www.adb.org/sites/default/files/project-documents/51073/51073-003-51073-004-pp-en.pdf"],["ICIP domestic control register — research/raw/tenders-centre.json (88 Union-government awards, 2019–2026)","research/raw/tenders-centre.json"]], domain: "contracts" },
  { claim: "Chinese contractors were shut out of Indian public works only after the 2020 border clash; before that they were a routine part of lender-funded procurement.", status: "established", strongestCase: "World Bank notices record Chinese winners on POWERGRID transformer, reactor and insulator packages (2011–2013) and a ₹471 cr EDFC signalling package to CRSC's Beijing institute (2016); 18 of 55 bidder-listed ICB awards had at least one Chinese bidder. The July 2020 GFR Order then made registration with DPIIT plus MEA/MHA clearance a precondition.", strongestCounter: "Chinese wins were concentrated in equipment (transformers, insulators) rather than civil works; the STEC tunnel package was the first large Chinese civil-works award in the NCR and drew objections precisely because it was unusual in kind.", whatWouldChangeThis: "A count of post-2020 WB/ADB India awards to Chinese firms (expected ≈0) would confirm the cut-off; evidence of Chinese civil-works wins before 2020 would strengthen 'routine'.", srcs: [["World Bank procurement notices API — project P115566 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P115566&rows=200"],["World Bank procurement notices API — project P101653 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P101653&rows=200"],["World Bank procurement notices API — project P131765 (contract award notices, awarded and evaluated bidders, prices)","https://search.worldbank.org/api/v2/procnotices?format=json&project_id=P131765&rows=20"],["PIB — Ministry of Finance, 'Restrictions on Public Procurement from certain countries', 2020-07-23 (Release ID 1640778)","https://pib.gov.in/PressReleasePage.aspx?PRID=1640778"],["ADB — Delhi–Meerut RRTS Procurement Plan Rev 7.0 (PDF: methods, awarded packages, estimated values, LOA dates)","https://www.adb.org/sites/default/files/project-documents/51073/51073-003-51073-004-pp-en.pdf"]], domain: "contracts" },
  { claim: "World Bank debarments single out Indian firms.", status: "unsupported", strongestCase: "54 Indian entries on the list, several of them listed companies (Madhucon Projects, A2Z Infra Engineering) with affiliates swept in.", strongestCounter: "3.6% of the list; ~20 distinct principal cases in 16 years, most small health/IT/rural-works firms; grounds are the standard fraudulent-practice clause applied worldwide; 30 of 52 rows are mechanical affiliate extensions of four cases.", whatWouldChangeThis: "A per-US$-lent comparison across the ten largest borrowers.", srcs: [["World Bank Listing of Ineligible Firms & Individuals — sanctions data API (as served to worldbank.org/debarred-firms, read 2026-09-26)","https://apigwext.worldbank.org/dvsvc/v1.0/json/APPLICATION/ADOBE_EXPRNCE_MGR/FIRM/SANCTIONED_FIRM"],["World Bank — Procurement: Listing of Ineligible Firms and Individuals (page that loads the API above)","https://www.worldbank.org/en/projects-operations/procurement/debarred-firms"]], domain: "contracts" },
  { claim: "The 1991 reforms were dictated by the IMF.", status: "contested", strongestCase: "The stand-by arrangement and CCFF drawdown coincided with, and were conditioned on, structural adjustment commitments — devaluation, de-licensing, opening protected sectors to foreign participation — and the government pledged national gold reserves as collateral to secure the loan, a strong signal of how constrained the negotiating position was.", strongestCounter: "The core liberalisation package (industrial de-licensing, trade reform, the start of financial-sector opening) was designed by the Rao government's own economic team and framed domestically as a long-overdue correction to decades of licence-permit-raj inefficiency; several of these ideas had been debated inside the Indian policy establishment since the mid-1980s (Rajiv Gandhi-era partial liberalisation) independent of any IMF programme, and the reforms continued and deepened long after the 1991-93 facility was repaid, when the IMF had no further leverage.", whatWouldChangeThis: "A primary IMF or RBI document itemising the specific conditions attached to the 1991 facility, compared line-by-line against the reform sequence actually enacted, would let this be scored rather than asserted either way — not obtained this session (imf.org and dea.gov.in both blocked).", srcs: [["Wikipedia — 1991 Indian economic crisis","https://en.wikipedia.org/wiki/1991_Indian_economic_crisis"]], domain: "debt-imf-people" },
  { claim: "India is heading for an external debt crisis.", status: "unsupported", strongestCase: "The absolute stock has grown continuously and substantially — from US$101bn in 2000 to US$716bn in 2024, a roughly sevenfold increase — and short-term debt is a meaningful roughly one-fifth of the total, which is the maturity structure that turned into a crisis in 1991.", strongestCounter: "External debt was 18.0% of GNI in 2023 and total debt service was 10.2% of exports in 2023 (World Bank), both moderate by international and by India's own 1991-era standards (when the debt-service ratio approached 30-35% of exports on a far smaller and more fragile reserve base); foreign-exchange reserves (not itemised in this file) have historically comfortably covered the stock; and the sovereign (public & publicly guaranteed) share of the debt has been shrinking as a proportion of the total relative to private/NRI-linked borrowing, which is a materially different risk profile from a government unable to service its own external obligations.", whatWouldChangeThis: "A sustained rise in the debt-service ratio past the 20-25% range historically associated with distress, or a sharp reserves drawdown alongside it, would move this out of \"unsupported.\"", srcs: [["World Bank API — DT.DOD.DECT.CD","https://api.worldbank.org/v2/country/IND/indicator/DT.DOD.DECT.CD?format=json&date=2000:2024&per_page=100"],["World Bank API — DT.TDS.DECT.EX.ZS","https://api.worldbank.org/v2/country/IND/indicator/DT.TDS.DECT.EX.ZS?format=json&date=2023&per_page=5"],["World Bank API — DT.DOD.DECT.GN.ZS","https://api.worldbank.org/v2/country/IND/indicator/DT.DOD.DECT.GN.ZS?format=json&date=2023&per_page=5"]], domain: "debt-imf-people" },
  { claim: "The IMF/World Bank control Indian policy.", status: "unsupported", strongestCase: "India has an active, continuous lending relationship with the World Bank (IBRD/IDA loans, detailed in the companion file worldbank-projects.json) that comes with project-level conditions, and the IMF's annual Article IV consultation produces policy recommendations that sometimes anticipate or echo budget measures.", strongestCounter: "India has not drawn on IMF balance-of-payments financing — the channel that gives the Fund real leverage over macroeconomic policy — since the 1991-93 facility; Article IV consultations are surveillance and advice, not conditionality, and India is free to (and often does) ignore them; multilateral (IBRD+IDA) debt was only US$39.3bn of a US$647.6bn total external debt stock in 2023 (about 6%), a small enough share that project-level conditions on that slice cannot plausibly be read as \"control\" of national policy.", whatWouldChangeThis: "Evidence of a live use-of-Fund-resources arrangement with binding macro conditionality, or a demonstrated pattern of budget reversals directly traceable to World Bank loan conditions across multiple sectors, would move this out of \"unsupported.\"", srcs: [["World Bank API — DT.DOD.MWBG.CD","https://api.worldbank.org/v2/country/IND/indicator/DT.DOD.MWBG.CD?format=json&date=2023&per_page=5"],["World Bank API — DT.DOD.DECT.CD","https://api.worldbank.org/v2/country/IND/indicator/DT.DOD.DECT.CD?format=json&date=2000:2024&per_page=100"]], domain: "debt-imf-people" },
  { claim: "India's IMF Executive Director (K.V. Subramanian) was removed for criticising the Fund / for misconduct.", status: "contested", strongestCase: "Business Standard, citing an Indian Express report and unnamed sources, reported that Subramanian's early exit followed his having raised concerns about IMF datasets — friction with the Fund over substance — and separately that questions had been raised about his promoting his own book while in the post; the recall also came days before an IMF board vote on aid to Pakistan that India opposed, which some read as the more consequential trigger.", strongestCounter: "The IMF itself told Business Standard on the record that ending his term was the Indian government's decision, not the Fund's — directly contradicting any reading in which the IMF pushed him out for criticising it; and no on-the-record government statement giving \"misconduct\" or any other formal reason has been found in accessible sources, nor has Subramanian himself been found on the record responding to either account (recorded as \"No response recorded\" per the contradiction rule).", whatWouldChangeThis: "An on-the-record statement from the Ministry of Finance, from the IMF beyond confirming who decided, or from Subramanian himself, giving a specific reason.", srcs: [["Business Standard — 2025-05-03","https://www.business-standard.com/economy/news/kv-subramanian-to-exit-imf-role-early-govt-begins-search-for-replacement-125050301015_1.html"],["Business Standard — 2025-05-05","https://www.business-standard.com/external-affairs-defence-security/news/krishnamurthy-subramanian-s-termination-was-india-s-call-says-imf-125050501223_1.html"]], domain: "debt-imf-people" },
  { claim: "Multilateral loans come with policy strings that override Parliament.", status: "contested", strongestCase: "Conditionality is real and documented: the IMF Monitor dataset codes 65,894 conditions in IMF programmes 1980–2019; the 1991 IMF/World Bank package was followed within weeks by the 1991-07-24 Budget's deregulation, 51% foreign-equity and disinvestment measures; World Bank DPF still disburses only on 'completion of a set of critical policy and institutional actions agreed between the Bank and the client' and 'maintenance of an adequate macroeconomic policy framework, as determined by the Bank with inputs from IMF assessments'. The Kerala DPO's eight prior actions are state policy acts. Loan agreements are signed by the executive under Article 292/293 with no parliamentary ratification, and Parliament has never legislated the borrowing limit Article 292 permits.", strongestCounter: "'Override' is the wrong verb. The Bank's own evaluator found that in India 'Conditionality was used sparingly and the commonality between the Bank's objectives and the government's was continually stressed', and that Bank ambitions were 'resisted by the authorities'. DPF is 'non-earmarked general budget financing that is subject to the borrower's own implementation processes' with a stated 'country ownership' principle; prior actions are drafted from the borrower's programme (Kerala's RKDP). The 1991 reforms were argued for by Indian economists before the crisis (Bhagwati–Panagariya; Ahluwalia; Rangarajan) and legislated where legislation was needed. The clearest external constraint on Bank lending to India — the 1998 nuclear-test sanctions — came from shareholder politics, not loan covenants. Parliament is bypassed by India's own executive treaty-making design, not by lenders.", whatWouldChangeThis: "Up to well-supported: an Indian statute or budget provision documented as enacted to satisfy a specific prior action against the recorded position of the ministry or a parliamentary committee (e.g. a DPL matrix line matched to a bill's statement of objects). Down to unsupported: the IMF Monitor India rows showing condition counts at or below programme means and no structural conditions in 1991 beyond the government's own Letter of Intent.", srcs: [["IMF Monitor — Conditionality","https://www.imfmonitor.org/conditionality"],["World Bank — DPF","https://www.worldbank.org/en/what-we-do/products-and-services/financing-instruments/development-policy-financing"],["OED India CAE 2001","http://documents1.worldbank.org/curated/en/813991468750240136/text/India-Country-assistance-evaluation.txt"],["Wikipedia — 1991 Indian economic crisis","https://en.wikipedia.org/wiki/1991_Indian_economic_crisis"],["Kerala DPO PGD77","https://documents.worldbank.org/curated/en/476681561946430308/text/India-First-Resilient-Kerala-Program-Development-Policy-Operation.txt"]], domain: "literature" },
  { claim: "Lender-funded contracts go to a closed club of contractors.", status: "contested", strongestCase: "For tied bilateral loans it is true by construction: JICA's MAHSR tranches state 'Procurement: Tied', restricting suppliers to Japanese firms in exchange for 0.1%/50-year money. For multilateral loans, Fazekas & Kocsis show that single bidding, short advertisement periods and procedure choice are measurable red flags of 'unjustified restriction of access to public contracts', and contracts.json records recurring winners and World Bank debarments of Indian firms. The OED found India's bid documents and contracting procedures weak in the 1990s.", strongestCounter: "The lender's own diagnosis of Indian procurement failure is delay — 'weaknesses in preparing bid documents ... and delays in contract awards following bid evaluation' — not capture. Multilateral procurement is open to all member-country bidders with published awards and a sanctions system, which is more transparent than most domestic procurement; a recurring set of large winners (L&T, Afcons, Tata Projects) is what a thin market for complex civil works looks like anywhere. Fazekas & Kocsis is a European study; no India single-bidding rate for lender-funded contracts has been computed in this fleet yet.", whatWouldChangeThis: "Up to well-supported: World Bank/ADB contract-award data for India showing single-bid or repeat-winner rates materially above the Bank-wide or CPPP baseline in the same sectors. Down to unsupported: rates at or below baseline, with the recurring winners explained by prequalification thresholds.", srcs: [["JICA press 2023-12","https://www.jica.go.jp/english/information/press/2023/20231222_30.html"],["CUP — Fazekas & Kocsis","https://www.cambridge.org/core/product/identifier/S0007123417000461/type/journal_article"],["OED India CAE 2001","http://documents1.worldbank.org/curated/en/813991468750240136/text/India-Country-assistance-evaluation.txt"]], domain: "literature" },
  { claim: "External borrowing under the NDA is more concessional / less than under the UPA.", status: "speculative", strongestCase: "Under NDA India signed the most concessional large loan in its history (JICA MAHSR: 0.1%, 50 years, 15-year grace) and used IDA blend terms by exception (Kerala 2019); the AIIB and NDB were added as lenders; DPOs brought budget support at IBRD rates.", strongestCounter: "The direction is mixed and the driver is structural: India graduated to 'only IBRD financial terms' on income grounds, so the concessional share of multilateral borrowing fell across the 2014 boundary regardless of government; JICA yen loans are concessional but tied; AIIB/NDB lend at near-IBRD terms. No consolidated series (DEA External Debt Status Report concessional-debt share, 2004–2026) was opened in this sweep, so neither 'more' nor 'less' has a denominator here.", whatWouldChangeThis: "The RBI/DEA external-debt releases for end-March 2004, 2014 and 2025 (concessional share, multilateral vs bilateral, average terms of new commitments) plus the worldbank-projects.json instrument mix by year would settle the volume and terms comparison; a discontinuity at 2014 not explained by IDA graduation would move it to contested; a smooth trend would move it to debunked as a partisan claim.", srcs: [["Kerala DPO PGD77","https://documents.worldbank.org/curated/en/476681561946430308/text/India-First-Resilient-Kerala-Program-Development-Policy-Operation.txt"],["JICA press 2023-12","https://www.jica.go.jp/english/information/press/2023/20231222_30.html"],["FPJ 2020-09-16","https://www.freepressjournal.in/business/did-the-modi-government-borrow-from-china-backed-aiib-amid-standoff"]], domain: "literature" },
  { claim: "Opposition-run states are denied external loans by the Centre (the DEA approval bottleneck).", status: "speculative", strongestCase: "The mechanism exists and bites: all state borrowing including externally aided projects needs Union consent under Article 293(3); the DEA fixed Kerala's FY2023-24 ceiling at ₹32,442 crore and counted off-budget (KIIFB-type) borrowings within it; Kerala sued, claiming ₹24,434 crore of denied space and 'extreme financial hardship'; the Supreme Court found the constitutional question serious enough for a five-judge bench. The World Bank's own 1990s practice of concentrating on 'reforming states' shows that state selection has always been discretionary.", strongestCounter: "No lender document, DEA file or minister's statement records a partisan ground for refusing a state's project; the same Union routed a US$250m IDA-blend DPO to LDF-run Kerala in 2019; the ceiling is a 3%-of-GSDP FRBM/Finance Commission rule applying to every state; the Court found prima facie merit in the Union's case that Kerala had over-borrowed in FY2017-18 to FY2019-20 and had 'no unutilized fiscal space'; and the Bank's 1990s focus states were governed by parties across the spectrum. The 'denial' Kerala documents is of borrowing room, not of external projects.", whatWouldChangeThis: "Up to contested/well-supported: a state-wise table of DEA-posed and approved EAPs 2014–2026 against population and prior lending showing a gap for opposition-run states that persists after controlling for fiscal indicators, or the Constitution Bench holding the ceiling's off-budget inclusion unconstitutional. Down to unsupported: the same table showing no gap.", srcs: [["Indian Kanoon — Kerala v Union 2024-04-01","https://indiankanoon.org/doc/191833676/"],["Kerala DPO PGD77","https://documents.worldbank.org/curated/en/476681561946430308/text/India-First-Resilient-Kerala-Program-Development-Policy-Operation.txt"],["OED India CAE 2001","http://documents1.worldbank.org/curated/en/813991468750240136/text/India-Country-assistance-evaluation.txt"]], domain: "literature" },
  { claim: "Chinese money captured Indian infrastructure companies before 2020.", status: "unsupported", strongestCase: "Brookings (2020): official Chinese FDI rose five-fold to US$8bn by 2017 and 'at least US$26 billion' counting announcements; infrastructure investment was 'dominated by state-owned enterprises'; Chinese state banks were major creditors of private Indian power and telecom groups (Reliance Power/Sasan, RCom, Lanco, Adani Power Maharashtra — bilateral-china.json), and a UK court ordered Anil Ambani to pay US$717m to Chinese banks in 2020; Banking on Beijing documents the risks of 'political capture' in China's debt-financed model; Press Note 3 (2020) was the government's own response.", strongestCounter: "'Captured' means control, and no documented case shows a Chinese state entity taking control of a listed Indian infrastructure operator: the money was Other Official Flows — commercial equipment-linked credit to private borrowers, priced as such — and the realised FDI was mostly consumer-technology and pharma equity; the largest 'infrastructure' numbers are pledged and unapproved (≈US$15bn). Creditor power over a defaulting borrower (the Ambani judgment) is what any lender has. Brookings itself recommends openness with safeguards, not a capture finding.", whatWouldChangeThis: "Up to contested: a documented change of control, board seat or step-in right exercised by a Chinese state lender over an Indian infrastructure company before 2020 (RoC filings, exchange disclosures). Down to debunked: AidData GCDF 3.0 India rows and DPIIT data confirming that pre-2020 Chinese official finance to Indian infrastructure was credit without equity or control rights.", srcs: [["Brookings 2020-03-30","https://www.brookings.edu/articles/following-the-money-china-incs-growing-stake-in-india-china-relations/"],["CUP — Banking on Beijing","https://www.cambridge.org/core/product/identifier/9781108564496/type/book"],["AidData GCDF 3.0","https://www.aiddata.org/data/aiddatas-global-chinese-development-finance-dataset-version-3-0"]], domain: "literature" },
  { claim: "The World Bank's Doing Business ranking was gamed for India.", status: "unsupported", strongestCase: "India's rank rose from 142 (DB2015) to 63 (DB2020) across exactly the editions (DB2018, DB2020) later found to contain manipulated data; the government used the rank as a performance claim; the WilmerHale report (per Wikipedia) found senior Bank leadership had pressured staff to change China's data, proving the index could be bent for a large borrower; India (Mumbai) does appear in the GIA report's list of DB16 data changes and a DB17 India construction-permits methodology concern was raised by the DB team itself.", strongestCounter: "The primary audit record names exactly four countries — Azerbaijan, Saudi Arabia and UAE (DB2020) and China (DB2018–20) — for nine irregularities, and India is not among them: the DB16 India (Mumbai) Getting Electricity item was one of five routine data changes reviewed, and management 'reconfirmed' the DB17 construction-permits concern 'were not data irregularities during GIA's verification'. Neither the 2021-09-16 discontinuation statement nor the Wikipedia summary of WilmerHale mentions India. India's rise coincided with documented reforms (insolvency code, GST, Delhi/Mumbai permit and electricity reforms) that the methodology rewarded.", whatWouldChangeThis: "Up to contested: the WilmerHale report or the DEC review showing that the DB16 India (Mumbai) change or the DB17 construction-permits treatment favoured India against the methodology, or evidence of Indian government pressure on Bank leadership comparable to the China finding. Down to debunked: release of the full DEC review confirming India's items were methodology-compliant.", srcs: [["GIA verification report 2020-12-08","http://documents1.worldbank.org/curated/en/569901608154479291/txt/Management-Review-of-Data-Irregularities-in-the-Doing-Business-Reports-from-2016-to-2020-Verification-Report.txt"],["World Bank statement 2021-09-16","https://www.worldbank.org/en/news/statement/2021/09/16/world-bank-group-to-discontinue-doing-business-report"],["Wikipedia — Ease of doing business index","https://en.wikipedia.org/wiki/Ease_of_doing_business_index"]], domain: "literature" },
  { claim: "The World Bank dictates Indian economic policy through loan conditions.", status: "unsupported", strongestCase: "DPF triggers for follow-on operations (SEBI ESG framework, carbon-market notification, Kerala private-finance instructions) are forward-looking commitments negotiated with Bank staff, and US$2.75bn of 2020 budget support was material at a moment of fiscal stress.", strongestCounter: "All 26 prior actions read across P173943, P174292 and P181032 were measures GoI had announced or legislated before appraisal; several predate the pandemic; ICR/IEG describe the operations as financing GoI's own programmes (PMGKY, Atmanirbhar, NGHM).", whatWouldChangeThis: "A prior action whose first public appearance is in a Bank document, or Bank mission records showing drafting before announcement.", srcs: [["Program Document P173943 (2020-04-30)","https://documents.worldbank.org/curated/en/685311589767271707/text/India-Accelerating-Indias-COVID-19-Social-Protection-Response-Program.txt"],["Program Document P174292 MSME DPL (2020-06-16)","https://documents.worldbank.org/curated/en/703561593828083607/text/India-Micro-Small-and-Medium-Enterprises-Emergency-Response-Development-Policy-Loan.txt"],["Program Document P181032 First Low-Carbon Energy DPL (2023-06-02)","https://documents.worldbank.org/curated/en/099060623092565311/text/BOSIB0342f50d505508c7803e3b35fb5c59.txt"],["IEG ICR Review P173943 (2024-10-06)","https://documents.worldbank.org/curated/en/099021425103520204/text/P173943-594240c2-796b-4b0c-80b6-a58ce6d8637c.txt"]], domain: "worldbank" },
  { claim: "The NDA government steers World Bank money to BJP-ruled states.", status: "unsupported", strongestCase: "Assam (BJP since 2016) is at 3.3x its population share and Gujarat rose from 0.29x to 1.24x; the state-attributed share of all lending doubled after 2014.", strongestCounter: "Kerala (LDF) 1.9x, Tamil Nadu (DMK/AIADMK) 1.75x and Andhra Pradesh (YSRCP 2019–24) 1.62x are above parity, while BJP-run Uttar Pradesh (0.61x), Madhya Pradesh (0.56x), Haryana (0.55x) and Chhattisgarh (0.18x) are below; under UPA the same lens gave HP 9.7x and Odisha 2.0x. The per-capita ratio is dominated by small hill and north-eastern states regardless of party.", whatWouldChangeThis: "A DEA or Bank allocation document tying state selection to political alignment, or a disbursement-based recomputation that produces a party-aligned ranking.", srcs: [["World Bank Projects API v3 — India, rows 0–999","https://search.worldbank.org/api/v3/projects?format=json&countrycode_exact=IN&rows=1000&os=0&fl=id,project_name,boardapprovaldate,closingdate,curr_total_commitment,curr_ibrd_commitment,curr_ida_commitment,borrower,impagency,status,pdo"],["World Bank Projects API v3 — India, rows 1000–1116","https://search.worldbank.org/api/v3/projects?format=json&countrycode_exact=IN&rows=1000&os=1000&fl=id,project_name,boardapprovaldate,closingdate,curr_total_commitment,curr_ibrd_commitment,curr_ida_commitment,borrower,impagency,status,pdo"],["census2011.co.in — state table reproducing Census 2011 final population totals (secondary)","https://www.census2011.co.in/states.php"]], domain: "worldbank" },
  { claim: "The COVID-19 World Bank loans put India in a debt trap.", status: "debunked", strongestCase: "US$2.75bn of emergency commitments (health US$1bn, social protection US$1.15bn, MSME US$0.75bn) were approved within three months in 2020.", strongestCounter: "All three were single-tranche budget support on 18.5-year IBRD or concessional IDA terms; the PDs themselves record that India's public debt is rupee-denominated, medium/long maturity and domestically held; the fiscal deficit (9.5% of GDP in FY21 per ICR) was financed overwhelmingly domestically.", whatWouldChangeThis: "Evidence that IBRD/IDA service costs became a binding constraint on the Union budget (they are a small fraction of external debt of ~US$716bn in 2024 per fleet SPEC).", srcs: [["Program Document P173943 (2020-04-30)","https://documents.worldbank.org/curated/en/685311589767271707/text/India-Accelerating-Indias-COVID-19-Social-Protection-Response-Program.txt"],["Program Document P174292 MSME DPL (2020-06-16)","https://documents.worldbank.org/curated/en/703561593828083607/text/India-Micro-Small-and-Medium-Enterprises-Emergency-Response-Development-Policy-Loan.txt"],["ICR P173943/P174027 (2024-04-22)","https://documents.worldbank.org/curated/en/099042224135030970/text/BOSIB-c35ef47d-c671-422e-acd1-d14436c5cc23.txt"],["World Bank press release 2020-05-14 — Board approves US$1bn COVID social protection programme","https://www.worldbank.org/en/news/press-release/2020/05/13/world-bank-covid-coronavirus-india-protect-poor"]], domain: "worldbank" },
  { claim: "The World Bank independently verified Swachh Bharat's open-defecation-free claims.", status: "contested", strongestCase: "The PforR disbursed US$1,259m against DLIs verified by NARSS household surveys, and IEG rated the outcome Satisfactory.", strongestCounter: "IEG rated efficacy 'Substantial with some shortcomings', programme cost came in at US$14.6bn against US$22bn appraised, US$241m was left undisbursed, and the operation was restructured four times to reach closing; verification was of programme indicators, not of the Government's ODF declarations as such.", whatWouldChangeThis: "Publication of the NARSS micro-data and the DLI verification protocols; independent replication of ODF rates.", srcs: [["IEG ICR Review P153251 Swachh Bharat Mission Support Operation (2023-09-15)","https://documents.worldbank.org/curated/en/099091523140562778/text/P15325104d51050080b0620ff05fe21c20f.txt"]], domain: "worldbank" },
];

